// examples/09-kitchen-sink/workflow.js
async function summarize(path, canonical) {
  const queue = [];
  queueMicrotask(() => queue.push("micro"));
  await Promise.resolve();
  const records = [
    { id: "b", rank: 2 },
    { id: "a", rank: 1 },
    { id: "c", rank: 2 }
  ];
  records.sort((left, right) => left.rank - right.rank);
  return {
    path,
    canonical,
    order: records.map((record) => record.id).join(","),
    queue: queue.join(",")
  };
}

// examples/09-kitchen-sink/entry.js
var entry_default = (async () => {
  const doc = document("path/to/doc");
  const canonical = document.canonical("path/to/doc");
  const result = await summarize(doc.path, canonical.canonical);
  Host.v1.emit({ kind: "kitchen", result });
  return result;
})();
export {
  entry_default as default
};

